import React from 'react';
import './Auth.css';

const Dashboard = ({ user, onLogout }) => {
  const movies = [
    {
      id: 1,
      title: 'Avengers: Endgame',
      genre: 'Action',
      duration: '3h 1m',
      rating: 'PG-13',
      description: 'The epic conclusion to the Infinity Saga.'
    },
    {
      id: 2,
      title: 'The Batman',
      genre: 'Action, Crime',
      duration: '2h 56m',
      rating: 'PG-13',
      description: 'The Dark Knight of Gotham City begins his war on crime.'
    },
    {
      id: 3,
      title: 'Spider-Man: No Way Home',
      genre: 'Action, Adventure',
      duration: '2h 28m',
      rating: 'PG-13',
      description: 'Spider-Man seeks the help of Doctor Strange when his secret identity is revealed.'
    },
    {
      id: 4,
      title: 'Dune',
      genre: 'Sci-Fi',
      duration: '2h 35m',
      rating: 'PG-13',
      description: 'A noble family becomes embroiled in a war for control over the galaxy\'s most valuable asset.'
    }
  ];

  console.log('🎬 Dashboard loaded for user:', user);

  return (
    <div className="container">
      <div className="card">
        <div style={{ 
          display: 'flex', 
          justifyContent: 'space-between', 
          alignItems: 'center', 
          marginBottom: '30px',
          flexWrap: 'wrap',
          gap: '20px'
        }}>
          <div>
            <h1 style={{ color: '#333', marginBottom: '10px' }}>
              Welcome to Movie Ticket App!
            </h1>
            <p style={{ color: '#666', fontSize: '18px' }}>
              Hello, <strong>{user?.username}</strong>! Ready to book some movies?
            </p>
          </div>
          <button 
            onClick={onLogout} 
            className="btn btn-secondary"
            style={{ minWidth: '120px' }}
          >
            Logout
          </button>
        </div>

        <div className="card">
          <h2 style={{ marginBottom: '20px', color: '#333' }}>🎥 Now Showing</h2>
          <div style={{ 
            display: 'grid', 
            gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', 
            gap: '25px' 
          }}>
            {movies.map(movie => (
              <div 
                key={movie.id} 
                style={{
                  border: '1px solid #e1e5e9',
                  borderRadius: '15px',
                  padding: '20px',
                  textAlign: 'center',
                  background: 'white',
                  boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
                  transition: 'transform 0.2s ease, box-shadow 0.2s ease'
                }}
                onMouseEnter={(e) => {
                  e.currentTarget.style.transform = 'translateY(-5px)';
                  e.currentTarget.style.boxShadow = '0 8px 15px rgba(0, 0, 0, 0.2)';
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.transform = 'translateY(0)';
                  e.currentTarget.style.boxShadow = '0 4px 6px rgba(0, 0, 0, 0.1)';
                }}
              >
                <div style={{
                  width: '100%',
                  height: '200px',
                  backgroundColor: '#f8f9fa',
                  borderRadius: '10px',
                  marginBottom: '15px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  color: '#666',
                  fontSize: '14px',
                  border: '2px dashed #dee2e6'
                }}>
                  🎬 {movie.title}
                </div>
                <h3 style={{ 
                  marginBottom: '10px', 
                  color: '#333',
                  fontSize: '20px'
                }}>
                  {movie.title}
                </h3>
                <p style={{ color: '#666', marginBottom: '5px' }}>
                  <strong>Genre:</strong> {movie.genre}
                </p>
                <p style={{ color: '#666', marginBottom: '15px' }}>
                  <strong>Duration:</strong> {movie.duration} • <strong>Rating:</strong> {movie.rating}
                </p>
                <p style={{ 
                  color: '#888', 
                  fontSize: '14px',
                  marginBottom: '15px',
                  fontStyle: 'italic'
                }}>
                  {movie.description}
                </p>
                <button 
                  className="btn btn-primary" 
                  style={{ width: '100%' }}
                  onClick={() => alert(`Booking ${movie.title} - Feature coming soon!`)}
                >
                  🎟️ Book Tickets
                </button>
              </div>
            ))}
          </div>
        </div>

        <div className="card">
          <h2 style={{ marginBottom: '20px', color: '#333' }}>👤 Your Profile</h2>
          <div style={{ 
            display: 'grid', 
            gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', 
            gap: '20px',
            background: '#f8f9fa',
            padding: '20px',
            borderRadius: '10px'
          }}>
            <div style={{ padding: '15px' }}>
              <strong>Username:</strong> {user?.username}
            </div>
            <div style={{ padding: '15px' }}>
              <strong>Email:</strong> {user?.email}
            </div>
            <div style={{ padding: '15px' }}>
              <strong>User ID:</strong> {user?.id}
            </div>
            <div style={{ padding: '15px' }}>
              <strong>Status:</strong> <span style={{ color: '#28a745' }}>✓ Active</span>
            </div>
          </div>
        </div>

        <div style={{ 
          textAlign: 'center', 
          marginTop: '40px', 
          padding: '20px',
          background: '#f8f9fa',
          borderRadius: '10px'
        }}>
          <h3 style={{ color: '#666', marginBottom: '10px' }}>
            🎉 Welcome to our Movie Ticket Booking Platform!
          </h3>
          <p style={{ color: '#888' }}>
            Browse our selection of movies and book your tickets easily.
            More features coming soon!
          </p>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;
